insert into pages (title, slug, kind, content, visibility) values ('Transformation and orchestration', 'transformation-and-orchestration', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is the build layer: how raw, loaded data becomes the clean, tested, modeled tables everything else reads, and how that work gets run reliably on a schedule. In 2026 that means, overwhelmingly, dbt for the transformation and an orchestrator (Airflow, Dagster, or dbt's own scheduler) for the runtime."}]},{"type":"paragraph","content":[{"type":"text","text":"It sits one level below the meaning work in "},{"type":"wikilink","attrs":{"title":"Data modeling"}},{"type":"text","text":" and the domain sections. Data modeling decides what the tables should mean; this section is the mechanics of actually producing them in the warehouse, testing them, and keeping them fresh."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Transformation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The dbt layer — ","marks":[{"type":"bold"}]},{"type":"text","text":"what the transformation layer is, how to structure a dbt project, materializations, modeling approaches, tests and contracts, and the 2026 dbt ecosystem."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Orchestration"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The runtime — ","marks":[{"type":"bold"}]},{"type":"text","text":"what orchestration is, the tool landscape, orchestrating dbt, CI/CD, and data observability."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The through-line is the one taro is built on: treat transformations as code, define each thing once, test it, and run it in a way both people and machines can trust. This section is the most tool-specific in the wiki, so the tool facts are dated; verify before you quote them."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What the transformation layer is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"What orchestration is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Transformation and orchestration voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('What the transformation layer is', 'what-the-transformation-layer-is', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The transformation layer is the T in the pipeline: where raw loaded data is cleaned, joined, reshaped, and modeled into analytics-ready tables. It's the heart of analytics engineering, and the reason it exists in the warehouse at all is a shift from ETL to ELT."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"ETL became ELT"}]},{"type":"paragraph","content":[{"type":"text","text":"In ETL you transform data before it lands, on a separate engine. In ELT you load raw data into the warehouse first and transform it there with SQL. Cheap, elastic cloud-warehouse compute (Snowflake, BigQuery, Databricks) made it economical to push transformation down into the warehouse, which is why the modern default is ELT with dbt doing the T."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What dbt actually does"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compiles and runs SQL — ","marks":[{"type":"bold"}]},{"type":"text","text":"you write select statements with Jinja templating; dbt compiles them to warehouse SQL and runs them in order."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Builds a DAG from refs — ","marks":[{"type":"bold"}]},{"type":"text","text":"ref() and source() express dependencies, so dbt knows the build order and what's downstream of what."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Materializes, tests, documents — ","marks":[{"type":"bold"}]},{"type":"text","text":"it persists each model (view, table, incremental), runs data tests, and generates docs and lineage."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"By 2026 dbt is table stakes: if you have a warehouse and an analytics team you almost certainly use it. The rest of this section is how to use it well. Start with "},{"type":"wikilink","attrs":{"title":"How to structure a dbt project"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"How to structure a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Materialization strategies"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"What analytics engineering is"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('How to structure a dbt project', 'how-to-structure-a-dbt-project', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Labs' \"How we structure our dbt projects\" guide is the de facto convention, and it's worth following because consistency beats cleverness here. The arc moves data from source-conformed (shaped by the systems it came from) to business-conformed (shaped by your concepts)."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The three layers"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Staging (stg_) — ","marks":[{"type":"bold"}]},{"type":"text","text":"one model per source table, named stg_[source]__[entity]. Light renaming, casting, and cleaning only. The atomic building blocks."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Intermediate (int_) — ","marks":[{"type":"bold"}]},{"type":"text","text":"purpose-built steps that stack logic and prepare entities for joining. Reusable, not user-facing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marts (fct_ / dim_) — ","marks":[{"type":"bold"}]},{"type":"text","text":"the business entities people actually query, organized by subject area. Facts are events and transactions; dimensions are descriptive attributes."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The other building blocks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sources — ","marks":[{"type":"bold"}]},{"type":"text","text":"raw warehouse tables declared in YAML and referenced via source()."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Seeds — ","marks":[{"type":"bold"}]},{"type":"text","text":"small CSVs version-controlled in the repo for lookup tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Snapshots — ","marks":[{"type":"bold"}]},{"type":"text","text":"capture slowly-changing (type 2) history over mutable source tables, the same idea as "}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This staging to intermediate to marts arc is the dbt expression of the modeling ideas in "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":": each layer has a clear grain, and the marts are where the business meaning lands. Deviate if you must, but declare it and stay consistent."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What the transformation layer is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Modeling approaches in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Materialization strategies', 'materialization-strategies', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A materialization is how dbt persists a model's results in the warehouse. The choice is a cost and performance tradeoff, and getting it right is one of the highest-leverage things an analytics engineer does for the warehouse bill."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The options"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"view — ","marks":[{"type":"bold"}]},{"type":"text","text":"virtual, no storage, recomputed on every read. Cheap to build, slower and costlier to query."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"table — ","marks":[{"type":"bold"}]},{"type":"text","text":"rebuilt in full each run. Fast reads, higher build cost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"incremental — ","marks":[{"type":"bold"}]},{"type":"text","text":"built once, then only new or changed rows are processed each run. Lowest recurring cost, most complexity."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ephemeral — ","marks":[{"type":"bold"}]},{"type":"text","text":"not built at all; inlined as a CTE into downstream models."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"materialized view — ","marks":[{"type":"bold"}]},{"type":"text","text":"the warehouse maintains an incrementally-refreshed view for you."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Incremental strategies"}]},{"type":"paragraph","content":[{"type":"text","text":"Incremental models pick how new data merges in: "},{"type":"text","text":"append","marks":[{"type":"bold"}]},{"type":"text","text":" (insert only, cheapest, risks duplicates), "},{"type":"text","text":"merge","marks":[{"type":"bold"}]},{"type":"text","text":" (upsert by a unique key), "},{"type":"text","text":"delete+insert","marks":[{"type":"bold"}]},{"type":"text","text":" (replace matching keys), "},{"type":"text","text":"insert_overwrite","marks":[{"type":"bold"}]},{"type":"text","text":" (replace whole partitions, ideal for date-partitioned data), and "},{"type":"text","text":"microbatch","marks":[{"type":"bold"}]},{"type":"text","text":" (time-based batches for large time-series). The "},{"type":"text","text":"is_incremental()","marks":[{"type":"italic"}]},{"type":"text","text":" macro wraps a WHERE clause so each run only scans recent rows."}]},{"type":"paragraph","content":[{"type":"text","text":"The tradeoff in one line: views cost storage nothing but pay on every read; tables pay to build; incremental pays least over time but adds real complexity around late-arriving data, backfills, and schema drift. Match the materialization to how the model is read and how often the data changes. This is "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}},{"type":"text","text":" thinking applied at the model level."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"How to structure a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Modeling approaches in dbt', 'modeling-approaches-in-dbt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt is unopinionated about modeling style; it runs whatever SQL you write. So the question of which modeling approach to use is yours, and it's the same set of choices covered conceptually in "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":", here viewed through how dbt teams actually build."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kimball dimensional — ","marks":[{"type":"bold"}]},{"type":"text","text":"star schemas of facts and dimensions matching how the business asks questions. Still the most widely adopted; usually your marts layer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One big table (OBT) — ","marks":[{"type":"bold"}]},{"type":"text","text":"a pre-joined, denormalized wide table. Simple and fast to read, scales poorly as logic grows. Common as a BI-serving layer on top of Kimball marts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data vault — ","marks":[{"type":"bold"}]},{"type":"text","text":"hubs, links, and satellites for a scalable, auditable integration layer. Usually sits below the marts, feeding dimensional models on top."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Activity schema — ","marks":[{"type":"bold"}]},{"type":"text","text":"a single time-series stream of entity-activity events. Elegant for sequence questions, niche in practice."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"In practice 2026 teams layer these: a normalized or vault integration layer, then Kimball dims and facts, then OBT marts for BI, which maps cleanly onto staging, intermediate, and marts. The medallion (bronze, silver, gold) framing is the same idea with different labels. Pick per use case, and let the "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" of each layer drive the choice."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"How to structure a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The semantic layer"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Testing & data quality', 'testing-and-data-quality', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tests are what make modeled data trustworthy instead of merely present. dbt's testing model has grown well past the four built-ins, and in 2026 it spans data tests, unit tests, and contracts."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Data tests"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Generic — ","marks":[{"type":"bold"}]},{"type":"text","text":"parameterized and reusable. The built-ins are unique, not_null, accepted_values, relationships; packages like dbt_utils and dbt_expectations add dozens more. Applied in YAML to columns, models, and sources."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Singular — ","marks":[{"type":"bold"}]},{"type":"text","text":"a one-off SQL assertion in tests/ that returns failing rows."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Unit tests and contracts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unit tests — ","marks":[{"type":"bold"}]},{"type":"text","text":"validate transformation logic against static mock inputs, meant to run in CI when code changes, not on every production run."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Model contracts — ","marks":[{"type":"bold"}]},{"type":"text","text":"declare a model's output shape (column names and types); the model fails to build if it doesn't conform. Models become APIs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Versions, access, groups — ","marks":[{"type":"bold"}]},{"type":"text","text":"version a public model so producers can ship breaking changes safely; access modifiers (private/protected/public) and groups draw ownership boundaries. Together with cross-project refs they're the basis of dbt Mesh."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The discipline: test the assumptions that, if violated, would make a number wrong, and run them where they're cheap to catch (CI for logic, every run for data). This is the same rigor described in "},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}},{"type":"text","text":", and it's what lets the finance "},{"type":"wikilink","attrs":{"title":"The MRR waterfall in dbt"}},{"type":"text","text":" assert its own correctness."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data observability"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The MRR waterfall in dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The dbt ecosystem in 2026', 'the-dbt-ecosystem-in-2026', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt the tool changed a lot in 2025 and 2026, and the changes matter for anyone betting a platform on it. The headline facts, dated because they move:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Fusion engine — ","marks":[{"type":"bold"}]},{"type":"text","text":"dbt Labs rewrote dbt in Rust (announced May 2025, built on the SDF acquisition from Jan 2025): much faster parsing, ahead-of-time compilation, column-level lineage, and a state-aware engine that rebuilds only what changed. It shipped under the source-available Elastic License 2.0, which drew real community concern about openness."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Core v2.0 — ","marks":[{"type":"bold"}]},{"type":"text","text":"alpha June 2026, open-source under Apache 2.0 on the same Rust runtime, ending the two-engine (Python Core vs Rust Fusion) split."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Fivetran merger — ","marks":[{"type":"bold"}]},{"type":"text","text":"dbt Labs and Fivetran merged (announced Oct 2025, completed June 1 2026), pitching an end-to-end stack \"for trusted AI agents.\" George Fraser CEO, Tristan Handy President."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The challengers"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLMesh (Tobiko Data) — ","marks":[{"type":"bold"}]},{"type":"text","text":"the main open-source challenger: virtual data environments (zero-copy dev clones, big warehouse-spend savings), native column-level lineage via SQL parsing, incremental by default, blue-green deploys. Tobiko was acquired by Fivetran in 2025."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dataform — ","marks":[{"type":"bold"}]},{"type":"text","text":"Google's BigQuery-native transformation tool, a comparison point but smaller mindshare."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The reason to track this in a wiki: tool consolidation and licensing decide what's safe to build on. The substance underneath the news is stable, transformation as version-controlled SQL with tests and lineage, but the corporate landscape is in flux, so treat any specific claim here as as-of-2026."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What the transformation layer is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The modern data stack"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('ML / AI integration', 'ml-ai-integration', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The modeled warehouse is the launch pad for machine learning and AI, and the handoff is a real analytics-engineering responsibility, not someone else's problem. Most of the value in an ML model is in clean, well-grained features, which is exactly what this section produces."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The handoffs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Features from marts — ","marks":[{"type":"bold"}]},{"type":"text","text":"the dims and facts feed feature tables. Engineering features in dbt (tested, versioned, at a defined grain) is what makes a downstream model trustworthy and reusable, as in "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Predictions back to the warehouse — ","marks":[{"type":"bold"}]},{"type":"text","text":"a model's output (a churn score, a forecast) comes back as another column the warehouse owns and serves, so it's governed like any other field."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Embeddings and vector stores — ","marks":[{"type":"bold"}]},{"type":"text","text":"text and semi-structured data turned into embeddings for semantic search and retrieval, increasingly stored in or beside the warehouse."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The 2026 twist is that AI is also pointed back at the modeling work itself: LLM-assisted documentation, semantic search over the catalog, and agents that read the warehouse. That only works if the data and definitions are governed, which is the whole argument of "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":". Feature engineering is the durable, human part; the model is the easy part."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Churn modeling in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('What orchestration is', 'what-orchestration-is', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Orchestration is the runtime control plane: it decides when each piece of the stack runs, in what order, and what happens when something fails. Two intertwined jobs, scheduling (trigger work on a cadence or an event) and dependency management (run B only after A, and stop or retry intelligently)."}]},{"type":"paragraph","content":[{"type":"text","text":"The central abstraction is the DAG, a directed acyclic graph where nodes are units of work and edges are dependencies, with no cycles so nothing loops forever. Orchestration is distinct from transformation: dbt defines what the data becomes, the orchestrator decides when dbt runs, after ingestion loads fresh data and before activation reads it. Even dbt's own engine doesn't replace an orchestrator."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Task-aware vs data-aware"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Task-centric — ","marks":[{"type":"bold"}]},{"type":"text","text":"the classic Airflow model: the orchestrator manages operations (run this task, then that one) and doesn't natively know what data a task produces, so it re-runs even when nothing changed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Asset / data-aware — ","marks":[{"type":"bold"}]},{"type":"text","text":"Dagster's software-defined assets, now also Airflow 3's asset scheduling: the orchestrator manages the data artifacts themselves, knows lineage, and can skip or trigger work based on whether a specific asset or partition actually updated."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The defining 2026 shift is from task-based toward asset and data-aware orchestration, largely because it lets you avoid recomputing unchanged data, which is a cost decision as much as a correctness one. See "},{"type":"wikilink","attrs":{"title":"The orchestration landscape"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The orchestration landscape"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Orchestrating dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"What the transformation layer is"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The orchestration landscape', 'the-orchestration-landscape', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The 2026 orchestration market sorts along one axis (task-centric vs asset-centric) and one decision (run it yourself vs managed)."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Apache Airflow — ","marks":[{"type":"bold"}]},{"type":"text","text":"the incumbent and safest default: widest operator ecosystem, largest community. Airflow 3 added asset-aware scheduling, DAG versioning, and (3.2) asset partitioning, narrowing the gap with Dagster."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dagster — ","marks":[{"type":"bold"}]},{"type":"text","text":"the asset-centric challenger built around software-defined assets and asset checks. Best fit for dbt-heavy analytics-engineering shops: native lineage, selective re-materialization, strong local dev."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefect — ","marks":[{"type":"bold"}]},{"type":"text","text":"Python-first (\"just write Python\"), with a newer asset layer. Lighter ops, good developer experience."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kestra — ","marks":[{"type":"bold"}]},{"type":"text","text":"declarative YAML orchestration, language-agnostic, pitched as the fit for an AI-generates-configs world."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Cloud scheduler — ","marks":[{"type":"bold"}]},{"type":"text","text":"built-in cron and event-driven jobs; simplest if you're all-in on dbt, but not a general multi-system orchestrator."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Managed — ","marks":[{"type":"bold"}]},{"type":"text","text":"Google Cloud Composer and AWS MWAA (managed Airflow), Astronomer Astro, Dagster+ and Prefect Cloud. Trade ops burden for predictable spend."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Rule of thumb for 2026: Airflow if you already run it at scale or need general workflow orchestration; Dagster if you're starting fresh and dbt-native; Prefect or Kestra if developer experience or declarative config is the priority. Whatever you pick, it has to play well with dbt, which is "},{"type":"wikilink","attrs":{"title":"Orchestrating dbt"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"What orchestration is"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Orchestrating dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Orchestrating dbt', 'orchestrating-dbt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Running dbt on a schedule is the most common orchestration job in an analytics stack, and there are three well-worn ways to do it."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Airflow via Cosmos — ","marks":[{"type":"bold"}]},{"type":"text","text":"Astronomer's open-source Cosmos renders each dbt model as a separate Airflow task, giving model-level visibility, parallelism, and failure isolation inside the tool most data engineers already run. The most widely deployed option."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dagster asset-per-model — ","marks":[{"type":"bold"}]},{"type":"text","text":"Dagster parses the dbt manifest and creates one asset per dbt node, so models become first-class assets with live lineage, selective re-materialization, and asset checks over dbt tests. The most native experience."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Cloud jobs — ","marks":[{"type":"bold"}]},{"type":"text","text":"cron and event-driven scheduling built in; simplest for all-dbt shops, limited for multi-system DAGs."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Run only what changed"}]},{"type":"paragraph","content":[{"type":"text","text":"The cost lever is state-based selection: "},{"type":"text","text":"dbt build --select state:modified+","marks":[{"type":"italic"}]},{"type":"text","text":" with deferral rebuilds only changed models and their children by comparing against a production manifest. dbt's state-aware engine automates this from code or data changes, with reported double-digit warehouse-cost savings. This is the same idea as asset-aware orchestration, applied to the model graph."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The orchestration landscape"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Materialization strategies"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('CI/CD and DataOps', 'ci-cd-and-dataops', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DataOps is the framing that data pipelines deserve the same engineering rigor as software: version control, automated testing, environment promotion, and continuous integration. In dbt that has a concrete shape."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Slim CI — ","marks":[{"type":"bold"}]},{"type":"text","text":"on a pull request, build only the modified models and their children against production state, instead of rebuilding the whole project. Fast, cheap, and enough to catch breakage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deferral — ","marks":[{"type":"bold"}]},{"type":"text","text":"CI compiles the PR's code but defers unbuilt upstream models to the production environment, so a leaf change doesn't rebuild the entire DAG."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt build in CI — ","marks":[{"type":"bold"}]},{"type":"text","text":"runs models and tests together in dependency order against an ephemeral PR schema; the --empty flag does a schema-only dry run to validate compilation cheaply."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLFluff — ","marks":[{"type":"bold"}]},{"type":"text","text":"a configurable SQL linter run in CI on changed files to enforce style and catch errors before review."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The backbone is environment separation: dev, an ephemeral CI schema per PR, and prod, with deferral connecting them. Done well, a model can't reach production without passing its tests, which is what makes the warehouse trustworthy enough to serve people and agents. It's "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" turned into a gate, and it pairs with "},{"type":"wikilink","attrs":{"title":"Data observability"}},{"type":"text","text":" for what happens after deploy."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data observability"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Orchestrating dbt"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Data observability', 'data-observability', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tests catch the problems you anticipated. Observability catches the ones you didn't, by monitoring the health of the data itself, not just whether the job ran. The pillars are freshness, volume, schema, distribution, and lineage."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Freshness — ","marks":[{"type":"bold"}]},{"type":"text","text":"did the data arrive on time. dbt source freshness is the built-in check; gate downstream runs on it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anomalies — ","marks":[{"type":"bold"}]},{"type":"text","text":"volume and distribution shifts that no fixed test would catch. Tools like Monte Carlo learn normal patterns and alert on deviation; Elementary does this dbt-natively from run artifacts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lineage — ","marks":[{"type":"bold"}]},{"type":"text","text":"table and increasingly column-level, for impact analysis (what breaks if this changes) and root cause (why is this dashboard wrong)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The relationship to orchestration is tightening: the asset-aware model puts data-health signals inside the runtime, so the orchestrator can skip, alert, or block downstream rather than failing silently. Observability is the operational half of trust, the same goal as "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" from the other direction, and it's what catches the reconciliation drift described in "},{"type":"wikilink","attrs":{"title":"Reconciling the metrics layer with the GL"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"What orchestration is"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Transformation and orchestration voices and canon', 'transformation-orchestration-voices', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This corner of the field has a clearer canon than the business-domain sections, anchored by the tool vendors and their founders."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Transformation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Labs and Tristan Handy — ","marks":[{"type":"bold"}]},{"type":"text","text":"coined \"analytics engineer\" and built the category-defining tool. The \"How we structure our dbt projects\" guide and Coalesce conference are the practical canon."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tobiko Data — ","marks":[{"type":"bold"}]},{"type":"text","text":"the SQLMesh team and the sharpest critics of dbt's licensing and full-refresh model; worth reading as the loyal opposition."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Orchestration"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Maxime Beauchemin — ","marks":[{"type":"bold"}]},{"type":"text","text":"created Apache Airflow at Airbnb and wrote the foundational \"Rise of the Data Engineer.\" Now at Preset (Superset)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nick Schrock — ","marks":[{"type":"bold"}]},{"type":"text","text":"founder of Dagster, previously co-created GraphQL; the \"build around assets, not tasks\" thesis."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Communities and reading"}]},{"type":"paragraph","content":[{"type":"text","text":"Coalesce, the dbt community, Airflow Summit, Daniel Beach's Data Engineering Central, and the observability vendors (Monte Carlo, Elementary) as publishers. The live 2026 debate is task-centric vs asset-centric and open-source vs managed."}]},{"type":"paragraph","content":[{"type":"text","text":"Tool facts in this section are dated to 2025 and 2026 and move fast. Confirm versions, releases, and corporate news before relying on them.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
